INSERT INTO table1 (c3, c1, c2) VALUES (2, 1, 1);
INSERT INTO table1 (c3, c1, c2) VALUES (NULL, 1, 1);

-- There are no INSERT statements because under the given schema constraints the two queries are equivalent.
-- For example, consider the sample data below. Both Q1 and Q2 return {1}:

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'S8', 1);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'IPHONE', 1);

INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 10, 1, '2020-01-01', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 20, 2, '2020-01-02', 1, 1);

-- Q1 returns 1 because only the row with c3=1 (mapping to a 'S8' row) is selected, and its c1=1 is not in the subquery (which returns 2 from the IPHONE row).
-- Q2 returns 1 by analogous reasoning.

-- In every instance that meets the schema constraints both queries compute the same result.

