-- The following INSERT statements assume that foreign-key and primary-key checks are temporarily disabled so that duplicates in table2 are allowed for testing purposes.
PRAGMA foreign_keys = OFF;  -- disable FK checks (for SQLite, for example)

-- Inserting duplicate values in table2 (this breaks the primary key constraint, but serves as a counterexample)
INSERT INTO table2(c2) VALUES (1);
INSERT INTO table2(c2) VALUES (1);

-- Inserting a row in table1 referring to the duplicate value in table2
INSERT INTO table1(c1, c2) VALUES (10, 1);

-- After these inserts:
-- For Q1, the subquery (SELECT COUNT(DISTINCT c2) FROM table2) returns 1, and the group in table1 has COUNT(DISTINCT c2)=1, so Q1 returns 10.
-- For Q2, the subquery (SELECT COUNT(*) FROM table2) returns 2, but the group in table1 still has COUNT_P=1, so Q2 returns no rows.

schema:
