INSERT INTO table1 (c1) VALUES (7);

-- Q1 computes MIN(ABS(1-3), ABS(1-7), ABS(3-7), ...) = MIN(2, 6, 4, 2, 6, 4) = 2
-- Q2 computes the positive differences from ordered pairs (3-1, 7-1, 7-3) = (2, 6, 4) and returns 2
-- Therefore, both queries return 2 and no counterexample (test data where they differ) exists.

