INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 20, 0);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 30, 0);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-05', 40, 0);

