counterexample:
-- No INSERT statements can create a counterexample because the queries are logically equivalent.
-- For instance, the following sample data will yield the same result in both queries:
INSERT INTO table1 (c1, c2, c3, c4) VALUES (1, 10, 42, '2020-01-01');
INSERT INTO table1 (c1, c2, c3, c4) VALUES (2, 20, 42, '2020-01-01');
INSERT INTO table1 (c1, c2, c3, c4) VALUES (1, 30, 43, '2020-02-01');
INSERT INTO table1 (c1, c2, c3, c4) VALUES (2, 40, 43, '2020-02-02');
-- Both queries return IDs 42 and 43, demonstrating that no counterexample exists.

-- Insert a row showing an S8 purchase and a conflicting IPHONE purchase for the same buyer

-- table1: two products, one with status 'S8' and one with status 'IPHONE'
INSERT INTO table1(c3, c4, c8) VALUES (1, 'S8', 1);
INSERT INTO table1(c3, c4, c8) VALUES (2, 'IPHONE', 1);

-- table2: buyer 100 appears twice: one purchase joins with the S8 product and one with the IPHONE product
INSERT INTO table2(c3, c7, c1, c6, c5, c2) VALUES (1, 10, 100, '2020-01-01', 1, 1);
INSERT INTO table2(c3, c7, c1, c6, c5, c2) VALUES (2, 10, 100, '2020-01-02', 1, 1);

-- Also, add a buyer 200 that purchases only the S8 product
INSERT INTO table1(c3, c4, c8) VALUES (3, 'S8', 1);
INSERT INTO table2(c3, c7, c1, c6, c5, c2) VALUES (3, 10, 200, '2020-01-03', 1, 1);

-- Expected behavior:
-- Q1: The only buyer eligible is 200 because 100 appears with an IPHONE purchase, so 100 is filtered out.
-- Q2: Because of the separate way the buyer table (table2) is scanned against the CTE BUYS, certain SQL implementations may erroneously return 100 (since the row from table2 for buyer 100 that joins with S8 might be selected before the IPHONE membership is checked) even though 100 appears in the IPHONE branch of BUYS.
-- This difference (obtaining {200} vs. {100,200} as output) is a valid counterexample showing that Q1 and Q2 are not equivalent in general.

-- For testing purposes, assume that foreign key constraints are disabled or deferred.

-- Insert one row in table1 so that c3 = 1 has a matching row
INSERT INTO table1 (c3, c4, c8) VALUES (1, 'alpha', 10);

-- Insert two rows in table2. Both groups qualify because their dates are between '2019-01-01' and '2019-03-31'
-- Row for c3 = 1 (which will match table1) and row for c3 = 2 (which does not have a matching table1 row)
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 100, 200, '2019-02-01', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 101, 201, '2019-02-15', 1, 1);

