-- Note: The following INSERT statements assume that duplicate logins on the same day for a given user are allowed (i.e. the PK constraint is relaxed for demonstration purposes).

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-01', 10, 0);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-02', 10, 0);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-02', 11, 0);

INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2021-01-01', 20, 0);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2021-01-03', 20, 0);

-- Explanation of the data:
-- For user 1 (c4=1), the MIN(c2) is '2021-01-01'. There are two rows with c2 = '2021-01-02' (i.e. MIN_DATE+1), so Q1 will add 2 to its numerator for user 1, whereas Q2 will count user 1 only once as having a consecutive login.
-- For user 2 (c4=2), the two logins are on '2021-01-01' and '2021-01-03', and so do not qualify as consecutive in either query.

-- With 2 distinct users, Q1 will compute the fraction as ROUND(2/2,2)=1.00, while Q2 will compute ROUND(1/2,2)=0.50.

