/* Assume for this test we can insert duplicate (c4,c2) pairs (i.e. the PK is disabled or relaxed). */

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 10, 0);
-- For group 1 the minimum date is 2020-01-01. Here we (illicitly) insert two rows for the consecutive date 2020-01-02
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 20, 0);
