-- In Q2 the subquery returns (4-1)=3. Then every pair (A,B) with A.c1 <> B.c1 satisfies ABS(A.c1 - B.c1) <= 3, so Q2 also returns 1.

-- Since every valid instance gives the same result for both queries, no counterexample exists.

-- The following INSERT statements illustrate the intended counterexample if the schema allowed duplicate login dates per user (i.e. if the PRIMARY KEY were defined only on c4 or not enforced for c2).
-- User 1: one login on the day after the first login
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2023-01-01', 10, 0);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2023-01-02', 20, 0);

-- User 2: two logins on the day after the first login (this violates the declared PRIMARY KEY, but illustrates the point if duplicates were allowed)
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2023-01-01', 30, 0);
-- The two rows below have the same date (min_date + 1) for user 2
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2023-01-02', 40, 0);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2023-01-02', 50, 0);

-- Under the relaxed constraint, Q1 would sum to (1 [from user 1] + 2 [from user 2]) = 3 and then divide by 2 (the number of users) giving 1.50,
-- while Q2 would count each user only once (1 + 1 = 2, then 2/2 = 1.00), so the queries would yield different results.

