INSERT INTO table1 (c1, c3, c2) VALUES (2, 'Bob', 20);

INSERT INTO table2 (c4, c1) VALUES (100, 1);
INSERT INTO table2 (c4, c1) VALUES (100, 2);
INSERT INTO table2 (c4, c1) VALUES (200, 1);

-- Running both Q1 and Q2 on the above data produces:
-- For c4 = 100: AVG = ROUND((10+20)/2,2) = 15.00
-- For c4 = 200: AVG = ROUND(10,2) = 10.00

-- Thus, while one might imagine a scenario where duplicate join rows create a discrepancy, the schema’s constraints guarantee equivalence of Q1 and Q2.

-- There is no valid INSERT test data that causes Q1 and Q2 to differ.
-- Any data inserted that satisfies the constraints will make both queries return the same results.

-- For example, the following sample data illustrates the identical behavior:

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'A', 1);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'B', 1);

INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 10, 100, '2019-02-01', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 11, 101, '2019-02-15', 1, 1);

INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 20, 200, '2019-02-01', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 21, 201, '2019-03-15', 1, 1);

-- For these INSERT statements, both Q1 and Q2 will return the same rows from table1.

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'A', 1);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'B', 1);

-- For c3 = 1, all dates are within the allowed range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 10, 100, '2019-01-15', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 11, 101, '2019-03-15', 1, 1);

-- For c3 = 2, one row is in-range and one is out-of-range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 12, 102, '2019-02-15', 1, 1);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 13, 103, '2019-04-15', 1, 1);

-- Now add a duplicate of the in-range row for c3 = 2. In a system that (nonstandardly) lets the join replication affect the aggregates in Q2 this extra row can cause the grouped row for c3=2 to meet the date conditions (if the duplicate is the only row that the engine happens to aggregate) while Q1 – which groups table2 only once – will correctly reject c3=2 because it sees the out-of-range date. 
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 14, 104, '2019-02-15', 1, 1);

