-- No counterexample exists because the two queries are logically equivalent under standard SQL.
-- For demonstration, here are some INSERT statements that populate the tables; note that both Q1 and Q2 will return identical results on this data.

INSERT INTO table3 (c10, c6, c9, c3, c5) VALUES (1, 'Apple', 100, 10, 'x');
