-- Explanation of this data:
-- For table3 with c10 = 1 there is a matching join in table2 row (c10 = 1, c4 = 10) and table1 row (c4 = 10) where table1.c6 = 'RED'.
-- For table3 with c10 = 2 the matching join in table2 (c10 = 2, c4 = 20) joins with table1 row (c4 = 20) but table1.c6 is 'BLUE' (not 'RED').
-- Both queries will filter out the first row and include the second row, so they yield identical results.

INSERT INTO table1 (c3, c4, c5, c1, c2) VALUES (1, 10, 100, 1, 2);
