INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-02', 21, 0);

-- Explanation of resulting aggregates:
-- For group INSTALL_DT = '2020-01-01':
-- Q1 will use the subquery (MIN(c2) per user) so that user 1 and user 2 count only once each, yielding INSTALLS = 2 and numerator = 2 (each has one row on '2020-01-02') so DAY1_RETENTION = 2/2 = 1.00.
-- Q2, however, when joining TEMP with table1, for user 1 the CASE WHEN INSTALL_DATE=c2 is true twice (because of the duplicate install rows) while for user 2 it is true once. Thus Q2 yields INSTALLS = 3 and, keeping the same numerator of 2, DAY1_RETENTION = 2/3 = 0.67.

