CREATE TABLE table1 (
    c1 INT,
    c3 VARCHAR(255),
    c2 INT,
    PRIMARY KEY (c1),
    CHECK (c2 >= 0)
);
CREATE TABLE table2 (
    c4 INT,
    c1 INT,
    PRIMARY KEY (c4, c1),
    FOREIGN KEY (c1) REFERENCES table1(c1)
);

